def buildElement(value, fontWeight, foreColor, bgColor):
	style = {}
	if fontWeight is not None:	style.update({"fontWeight": fontWeight})		
	if foreColor is not None: style.update({"color": foreColor}) 
	else: style.update({"color": colors[bgColor] if colors.has_key(bgColor) else ''})
	if bgColor is not None: style.update({'backgroundColor': bgColor})
	style.update({'borderColor': bgColor or '#000000', 'borderRadius': '4px', 'margin': '1px'})	
	return {'value': value, 'style':style}

self.view.custom.info = {"text": "Formatting items...", "type": "INFO", 'showBar': True}
tableColumns = self.view.custom.itemTable.tableColumns
attrNameList = []

data = system.kanoa.utilities.convertDatasetToJSON(value['data'])	

#To speed things up we'll create a dictionary mapping foreColors t bgColors
bgColors = list({
    color
    for item in data
    for color in (item.get('itemColor'), item.get('itemClassColor'))
    if color
})
foreColors = [system.kanoa.utilities.getContrastingColor(bgColor) for bgColor in bgColors]
colors = dict(zip(bgColors, foreColors))

for item in data:
	item['itemName'] = buildElement(item['itemName'], None, None, item['itemColor'] or item['itemClassColor'])
	item['itemClassPath'] = buildElement(item['itemClassPath'], None, None, item['itemClassColor'])

if value['options']['showItemAttributes']:
	itemAttributes = system.kanoa.utilities.convertDatasetToJSON(system.kanoa.item.getItemAttributes({}))			
	attributes = {}
	for attr in itemAttributes: attributes[attr['itemId']] = {}

	for attr in itemAttributes: attributes[attr['itemId']][attr['itemAttrName']] = attr['itemAttrValue']

	for item in data:				
		if not attributes.has_key(item['itemId']): continue
		for k,v in attributes[item['itemId']].items():
			attrNameList.append(k)
			item[k] = v

	attrNameList = list(set(attrNameList))

	for item in data:
		for name in attrNameList:
			if not name in item: item[name] = None

	tableColumns = self.view.custom.itemTable.defaultColumns + [self.view.getChild("root").createTableColumn(attr) for attr in attrNameList]

self.props.columns = tableColumns
self.view.custom.info = {"text": "", "type": "INFO", 'showBar': False}

return data

